/**
 * DevilLVUpRateData catalog — G-Type / GrowthType labels and ranked options.
 * Regenerated by scripts/wiki-export-growth-types.sh
 */
import growthTypesPayload from "@/content/armory/growth-types.json"
import { REUNION_BRANCH_NAMES } from "@/lib/demon-reunion-edit-shared"

export const GROWTH_TYPE_MAX = 255

export type GrowthTypeEntry = {
  id: number
  groupID: number
  subID: number
  name: string
  branchIndex: number | null
  branchName: string | null
}

export type RankedGrowthTypeOption = {
  id: number
  subID: number
  name: string
}

type GrowthTypesPayload = {
  byId: Record<string, GrowthTypeEntry>
  byBranch: Record<string, RankedGrowthTypeOption[]>
}

const catalog = growthTypesPayload as GrowthTypesPayload

export function getGrowthTypeEntry(id: number): GrowthTypeEntry | null {
  const entry = catalog.byId[String(Math.floor(id))]
  return entry ?? null
}

/** Human label for profile / lists, e.g. "Tiwaz of Daath" or "Growth 8". */
export function getGrowthTypeLabel(id: number): string {
  const n = Math.floor(Number(id) || 0)
  const entry = getGrowthTypeEntry(n)
  if (!entry) return n ? `Growth ${n}` : "—"
  if (entry.name) {
    if (
      entry.branchName &&
      entry.subID >= 1 &&
      !entry.name.toLowerCase().includes(entry.branchName.toLowerCase())
    ) {
      return `${entry.branchName} · ${entry.name}`
    }
    return entry.name
  }
  if (entry.branchName && entry.subID >= 1) {
    return `${entry.branchName} (rank ${entry.subID})`
  }
  return `Growth ${n}`
}

/** Ranked reunion options (subID 1–9) for each runestone branch. */
export function getRankedGrowthTypesByBranch(): Array<{
  branchIndex: number
  branchName: string
  options: RankedGrowthTypeOption[]
}> {
  return REUNION_BRANCH_NAMES.map((branchName, branchIndex) => ({
    branchIndex,
    branchName,
    options: catalog.byBranch[String(branchIndex)] ?? [],
  }))
}

export function isKnownGrowthType(id: number): boolean {
  return getGrowthTypeEntry(id) != null
}

export function clampGrowthType(id: number): number {
  return Math.max(0, Math.min(GROWTH_TYPE_MAX, Math.floor(Number(id) || 0)))
}
